package com.tehang.enterpriserisk.api;
import com.tehang.enterpriserisk.service.AuthService; import jakarta.servlet.http.HttpServletRequest; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/accounts") public class AccountController {private final AuthService auth; public AccountController(AuthService a){auth=a;} private void admin(HttpServletRequest r){if(!auth.hasPermission((String)r.getAttribute("role"),"ACCOUNT_MANAGE"))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN,"需要账号管理权限");} @GetMapping public List<Map<String,Object>> list(HttpServletRequest r){admin(r);return auth.accounts();} @GetMapping("/roles") public List<Map<String,Object>> roles(HttpServletRequest r){admin(r);return auth.enabledRoles();} @PostMapping public Map<String,Object> create(@RequestBody Req x,HttpServletRequest r){admin(r);return auth.save(null,x.loginAccount(),x.employeeName(),x.phone(),x.role(),x.password());} @PutMapping("/{id}") public Map<String,Object> update(@PathVariable long id,@RequestBody Req x,HttpServletRequest r){admin(r);return auth.save(id,null,x.employeeName(),x.phone(),x.role(),null);} @PostMapping("/{id}/status") public void status(@PathVariable long id,@RequestBody Status x,HttpServletRequest r){admin(r);auth.status(id,x.enabled());} @PostMapping("/{id}/reset-password") public void reset(@PathVariable long id,HttpServletRequest r){admin(r);auth.reset(id);} record Req(String loginAccount,String employeeName,String phone,String role,String password){} record Status(boolean enabled){} }
